import{_ as a,o as n,a as p,b as c}from"./app.BGziXukh.js";const l="/ascendc.github.io/assets/unaligned_in_c_api.CxYUU9fv.svg",t="/ascendc.github.io/assets/unaligned_out_c_api.Duh2pDaO.svg",o="/ascendc.github.io/assets/vec_addr_err_c_api.BOSysaXn.svg",i="/ascendc.github.io/assets/redundant_calc_c_api.DkdcVGCV.svg",_="/ascendc.github.io/assets/mask_dirty_c_api.Dz5KwnxV.svg",e="/ascendc.github.io/assets/dup_clear_c_api.Bg1cPKgg.svg",r="/ascendc.github.io/assets/pad_clear_c_api.BMIB3ALg.svg",w="/ascendc.github.io/assets/unpad_copy_c_api.Btet4-PN.svg",u="/ascendc.github.io/assets/gather_mask_c_api.Bfhr4JEC.svg",C=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/operator_practice"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程（C API）","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/vector_programming_c_api"},{"text":"非对齐场景","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/unaligned_scenario"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/unaligned_scenario.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/unaligned_scenario.md","outlineHeaders":[{"level":2,"title":"数据搬运和Vector计算的对齐要求","slug":"数据搬运和Vector计算的对齐要求","link":"#数据搬运和Vector计算的对齐要求"},{"level":2,"title":"非对齐处理方案","slug":"非对齐处理方案","link":"#非对齐处理方案"}],"lastUpdated":1795433433000}'),g={name:"guide/operator_practice/simd_operator_impl/vector_programming_c_api/unaligned_scenario.md"};function d(h,s,m,v,b,f){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>非对齐场景</h1><p>本节介绍非32字节对齐数据的更多处理方式，包括数据搬入、计算和搬出的处理。用户在实际算子开发中，可以参考如下方案介绍和算子样例灵活地处理非对齐场景。</p><h2 id="数据搬运和Vector计算的对齐要求">数据搬运和Vector计算的对齐要求<a class="header-anchor" href="#数据搬运和Vector计算的对齐要求">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 进行数据搬运和Vector计算时，对于搬运的数据长度和操作数的起始地址有如下的对齐要求：</p><ul><li>本节使用NPU架构版本3510接口。GM与UB之间搬运的长度需满足数据类型的字节对齐要求，无需一律为32字节倍数；UB起始地址须满足具体接口约束。非32字节对齐搬入时，UB应预留向上补齐到32字节后的空间。</li><li>通常情况下，进行Vector计算时，操作数的起始地址必须保证32字节对齐。具体对齐要求需要查阅对应的API参考进行确认。</li></ul></div><p>下文描述中的Global指Global Memory上的数据，Local指Local Memory上的数据，C API中分别通过GM指针和UB指针访问。</p><p>下面是一些非对齐搬运和计算的例子。</p><ul><li><p><strong>非对齐搬入</strong></p><p>当需要从Global拷贝11个half数值到Local时，若主动按32字节补齐搬运长度，可使用asc_copy_gm2ub拷贝16个half（32B）数据到Local上，Local[11]~Local[15]被写成无效数据-1。</p><p><strong>图1</strong> 非对齐搬入</p><p><img src="'+l+'" alt="非对齐搬入"></p></li><li><p><strong>非对齐搬出</strong></p><p>当需要从Local拷贝11个half数值到Global时，若主动按32字节补齐搬运长度，可使用asc_copy_ub2gm拷贝16个half（32B）数据到Global上，Global[11]~Global[15]被写成无效数据-1。</p><p><strong>图2</strong> 非对齐搬出</p><p><img src="'+t+'" alt="非对齐搬出"></p></li><li><p><strong>矢量计算起始地址非32字节对齐的错误示例</strong></p><p>矢量计算时需要保证起始地址32字节对齐，如下的示例中，从Local1[7]，即UB数组的第8个数开始计算，起始地址不满足32字节对齐，是错误示例。</p><p><strong>图3</strong> 矢量计算起始地址非32字节对齐的错误示例</p><p><img src="'+o+'" alt="矢量计算起始地址非32字节对齐的错误示例"></p></li></ul><h2 id="非对齐处理方案">非对齐处理方案<a class="header-anchor" href="#非对齐处理方案">​</a></h2><p><a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>和<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a>接口提供非对齐搬运的功能，如果基于该接口支持的产品开发算子（参见产品支持情况），则可以直接使用该接口解决非对齐场景下的搬运问题。原基础API版本使用DataCopyPad的完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/00_data_movement/data_copy_pad_gm2ub_ub2gm/README.md">DataCopyPad样例</a>。</p><p>对于使用对齐搬运接口的场景，可以参考如下的搬运方案处理。</p><p>首先，使用asc_copy_gm2ub、asc_copy_ub2gm对齐数据搬运接口进行数据搬运，若主动将每行搬入长度向上补齐到32字节，数据长度非对齐的情况下，从Global逐行搬运Tensor数据到Local中，Local中每行都存在冗余随机数据。</p><p>搬入后，进行矢量计算时对冗余数据的处理方式有以下几种：</p><ul><li><p><strong>冗余数据参与计算</strong>。一般用于elewise计算场景，冗余数据即使参与计算，也不影响最终结果，如下图所示：</p><p><strong>图4</strong> 冗余数据参与计算</p><p><img src="'+i+'" alt="冗余数据参与计算"></p></li><li><p><strong>通过mask参数掩掉冗余数据</strong>。一般用于轴归约计算等场景。如下图所示，为只对前4个half数据进行最小值归约计算，可以通过设置mask参数的方法掩掉冗余数据：</p><p><strong>图5</strong> 使用mask掩掉脏数据</p><p><img src="'+_+`" alt="使用mask掩掉脏数据"></p><p>示例片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">MaskMinVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">result</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">;</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">count</span><span class="p">);</span><span class="w"> </span><span class="c1">// 仅前4个元素参与运算</span>
<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_reduce_min</span><span class="p">(</span><span class="n">result</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">result</span><span class="p">,</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">count</span><span class="p">));</span>
<span class="p">}</span>
<span class="c1">// 在核函数中调用：</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">MaskMinVF</span><span class="o">&gt;</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">);</span>
</code></pre></div></li><li><p><strong>通过asc_duplicate_scalar逐行清零</strong>。计算前，针对每一行数据，调用C API <a href="../../../../api/SIMD-API/c_api/reg_compute/reg_broadcast/asc_duplicate_scalar.html">asc_duplicate_scalar</a>对冗余数据位置填充0值，通过非对齐存储指定仅后5个元素位置有效，将冗余数据填充为0，如下图所示：</p><p><strong>图6</strong> 通过asc_duplicate_scalar逐行清零</p><p><img src="`+e+`" alt="通过asc_duplicate_scalar逐行清零"></p><p>示例片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ClearRowsVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">zero</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_duplicate_scalar</span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">row</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">writer</span><span class="p">;</span>
<span class="w">        </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">11</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="n">zero</span><span class="p">,</span><span class="w"> </span><span class="mi">5</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">11</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="mi">5</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_mem_bar</span><span class="p">(</span><span class="n">VST_VST</span><span class="p">);</span><span class="w"> </span><span class="c1">// 等待本行存储完成，保持逐行清零的执行顺序</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">ClearRowsVF</span><span class="o">&gt;</span><span class="p">(</span><span class="n">input</span><span class="p">);</span>
</code></pre></div></li><li><p><strong>通过asc_duplicate_scalar一次性清零</strong>。计算前，针对多行数据，可以在一次VF调用中组合寄存器加载、asc_duplicate_scalar和非对齐存储，对多行冗余数据进行批量清零，保持原Pad示例每行6个有效half、10个填充half的布局。</p><p><strong>图7</strong> 通过asc_duplicate_scalar一次性清零</p><p><img src="`+r+`" alt="通过asc_duplicate_scalar一次性清零"></p><p>示例片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">ClearPaddingVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">writer</span><span class="p">;</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">zero</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_duplicate_scalar</span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">row</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">vector_half</span><span class="w"> </span><span class="n">value</span><span class="p">;</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="mi">6</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="n">zero</span><span class="p">,</span><span class="w"> </span><span class="mi">10</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">);</span>
<span class="p">}</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">ClearPaddingVF</span><span class="o">&gt;</span><span class="p">(</span><span class="n">outputLocal</span><span class="p">,</span><span class="w"> </span><span class="n">inputLocal</span><span class="p">);</span>
</code></pre></div></li></ul><p>最后，使用asc_copy_gm2ub、asc_copy_ub2gm对齐数据搬运接口进行数据搬出。若主动按32字节补齐搬出长度且满足UB起始地址要求，搬出时可以选择去除冗余数据或者带着冗余数据搬出的方式，有以下几种：</p><ul><li><p><strong>使用寄存器加载与非对齐存储去除冗余数据后搬出</strong>。待搬出的有效数据总长度满足32字节对齐时，可使用<a href="../../../../api/SIMD-API/c_api/reg_compute/store/asc_storeunalign.html">asc_storeunalign</a>逐行提取前6个half以去除冗余数据并完整搬出。如下图所示：</p><p><strong>图8</strong> 使用寄存器加载与非对齐存储去除冗余数据后搬出</p><p><img src="`+w+`" alt="使用寄存器加载与非对齐存储去除冗余数据后搬出"></p><p>示例片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CompactRowsVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">writer</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">row</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">vector_half</span><span class="w"> </span><span class="n">value</span><span class="p">;</span>
<span class="w">        </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">row</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">6</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="mi">6</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="mi">96</span><span class="p">);</span>
<span class="p">}</span>
<span class="c1">// 每行16个half，仅前6个有效；16行合计96个有效half。</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">CompactRowsVF</span><span class="o">&gt;</span><span class="p">(</span><span class="n">outputLocal</span><span class="p">,</span><span class="w"> </span><span class="n">inputLocal</span><span class="p">);</span>
<span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_copy_ub2gm</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">outputLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">96</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
</code></pre></div></li><li><p><strong>使用寄存器加载与非对齐存储收集有效数据后搬出</strong>。待搬出的有效数据总长度大于等于32字节时，可使用<a href="../../../../api/SIMD-API/c_api/reg_compute/store/asc_storeunalign.html">asc_storeunalign</a>重新收集有效数据，保证搬出的有效数据起始地址和数据长度32字节对齐。如下图所示：</p><p><strong>图9</strong> 使用寄存器加载与非对齐存储收集有效数据后搬出。</p><p><img src="`+u+`" alt="使用寄存器加载与非对齐存储收集有效数据后搬出"></p><p>示例片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CollectRangeVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">tail</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_load_unalign</span><span class="w"> </span><span class="n">reader</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">writer</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">value</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc_loadunalign_pre</span><span class="p">(</span><span class="n">reader</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">3</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_loadunalign</span><span class="p">(</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="n">reader</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">3</span><span class="p">);</span><span class="w"> </span><span class="c1">// 收集索引3-18位置的16个half</span>
<span class="w">    </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">tail</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">tail</span><span class="p">,</span><span class="w"> </span><span class="n">writer</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="p">}</span>
<span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">CollectRangeVF</span><span class="o">&gt;</span><span class="p">(</span><span class="n">tailLocal</span><span class="p">,</span><span class="w"> </span><span class="n">outputLocal</span><span class="p">);</span>
<span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">asc_copy_ub2gm</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">outputLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">);</span>
<span class="n">asc_copy_ub2gm</span><span class="p">(</span><span class="n">dstGlobal</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="n">tailLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span><span class="w"> </span><span class="c1">// 覆盖Global索引3-18位置的数据</span>
</code></pre></div></li></ul><p>上述片段使用3510的寄存器接口，通过asc_vf_call调用矢量函数。其中asc_reduce_min用于归约，asc_duplicate_scalar生成零值，asc_loadalign、asc_loadunalign与asc_storeunalign组合完成数据整理，未使用2201的存储器矢量接口。</p><p>代码包含头文件<code>&quot;c_api/asc_simd.h&quot;</code>，并在<code>asc_init()</code>之后执行。各片段独立说明处理方法，VF函数定义须放在核函数之前，示例中的调用语句置于核函数中；输入应先完成搬入及相应同步。所有整寄存器加载都要求实际读取范围可访问：MaskMinVF至少预留128个half，ClearPaddingVF和CompactRowsVF的源缓冲区至少预留384个half，CollectRangeVF源缓冲区至少预留160个half。对齐搬运涉及的额外GM读写空间必须已分配，不能将图中的冗余空间视为可以越界访问。图中数据布局与原例保持一致，函数名称与本页实现对应。通用要求参见<a href="overview.html#c_api_usage">概述</a>。</p></article></div>`,1)])])}const P=a(g,[["render",d]]);export{C as __pageData,P as default};
